// headPushedOrigins points the HEAD of each of the sandbox's origins that has
// received a delivery at what arrived: a bare origin's as its owner
// (headOriginAtWhatArrived), and a cache namespace's in the cache. A source
// with neither is not delivered by a client.
func (r *DockerSandboxRuntime) headPushedOrigins(ctx context.Context, sandboxID string, sources []sandboxconfig.RuntimeSource) error {
	caches, err := r.readSourceCaches(sandboxID)
	if err != nil {
		return err
	}
	for _, source := range sources {
		if key := caches[source.Slug]; key != "" {
			path, release, err := r.gitCache.Use(ctx, key)
			if err != nil {
				return fmt.Errorf("source %q cache: %w", source.Slug, err)
			}
			err = r.gitCache.EnsureHead(ctx, path, sandboxID, source.Slug, "")
			release()
			if err != nil {
				return fmt.Errorf("source %q cache: %w", source.Slug, err)
			}
			continue
		}
		origin := r.sandboxOriginPath(sandboxID, source.Slug)
		info, err := os.Stat(origin)
		if err != nil {
			if os.IsNotExist(err) {
				continue
			}
			return err
		}
		uid, gid := fileOwner(info)
		if err := headOriginAtWhatArrived(ctx, origin, uid, gid); err != nil {
			return fmt.Errorf("source %q origin: %w", source.Slug, err)
		}
	}
	return nil
}

// ErrSourceStatesUnsupported is a sandbox agent that cannot say how far its
// sources have converged: an image whose agent predates the route, or one with
// no source converger. Waiting on it would wait forever.
var ErrSourceStatesUnsupported = errors.New("the sandbox's image predates cloning its own sources; rebuild it on a current discobox base")

// awaitSourcesMaterialized waits until the sandbox reports every source named
// materialized. A source whose clone keeps failing, or that the sandbox never
// starts on, fails the wait with what the sandbox said.
//
// Each read is reported as the phase this wait is, naming the first source
// not yet materialized — by its entry in labels — and how far its clone has
// got. A clone of a large remote is minutes, and the phase published once
// as the wait began would age out of what a client counts as current long
// before it ends (#138).
func (r *DockerSandboxRuntime) awaitSourcesMaterialized(ctx context.Context, dial Dialer, sandboxID string, sources []sandboxconfig.RuntimeSource, labels map[string]string) error {
	// The record is the last report and is never cleared, so the wait ends
	// on the bare phase: a CLI that predates clone progress fails to decode a
	// record carrying it (ADR 0118), and only a create still waiting should.
	// It is sent however the create's context ended, and bounded on its own so
	// a control plane that stalls cannot hold the create's result.
	defer func() {
		final, cancel := context.WithTimeout(context.WithoutCancel(ctx), sourceFinalPhaseTimeout)
		defer cancel()
		r.publishSandboxPhase(final, sandboxID, PhaseMaterializingSource)
	}()
	ctx, cancel := context.WithTimeout(ctx, sourceSettleTimeout)
	defer cancel()
	start := time.Now()
	// The first failure seen may be from before this wait woke the agent, so
	// only a failure reported later counts, and only a run of them.
	firstSeen := map[string]sourceState{}
	failures := map[string]int{}
	for {
		states, err := r.readSourceStates(ctx, dial, sandboxID)
		if errors.Is(err, ErrSourceStatesUnsupported) {
			return fmt.Errorf("sandbox %s: %w", sandboxID, err)
		}
		if err != nil {
			slog.WarnContext(ctx, "read sandbox source states", "sandboxId", sandboxID, "error", err)
		}
		pending := 0
		for _, source := range sources {
			state, ok := states[source.Slug]
			if ok && state.State == sourceStateMaterialized {
				continue
			}
			if pending == 0 {
				r.publishSandboxCloneProgress(ctx, sandboxID, cloneProgress(labels, source.Slug, state))
			}
			pending++
			if !ok {
				continue
			}
			first, seen := firstSeen[source.Slug]
			if !seen {
				firstSeen[source.Slug] = state
				first = state
			}
			switch {
			case state.State == sourceStateFailed && !state.UpdatedAt.Equal(first.UpdatedAt):
				failures[source.Slug]++
				firstSeen[source.Slug] = state
				if failures[source.Slug] >= sourceFailureLimit {
					return fmt.Errorf("materialize source %q: %s", source.Slug, state.Error)
				}
			case state.State == sourceStateWaiting && time.Since(start) > sourceWaitingTimeout:
				return fmt.Errorf("materialize source %q: its origin %s has nothing to clone", source.Slug, source.OriginURL)
			}
		}
		if pending == 0 {
			return nil
		}
		select {
		case <-ctx.Done():
			return fmt.Errorf("wait for the sandbox to materialize its sources: %w", ctx.Err())
		case <-time.After(sourceStatePollInterval):
		}
	}
}

// cloneProgress is what a status line says about a source the sandbox has not
// materialized: what it is, and how far its clone has got when the sandbox
// has said.
func cloneProgress(labels map[string]string, slug string, state sourceState) CloneProgress {
	clone := CloneProgress{Source: labels[slug]}
	if clone.Source == "" {
		clone.Source = slug
	}
	if progress := state.Progress; progress != nil && state.State == sourceStateCloning {
		clone.Stage = progress.Stage
		clone.Objects, clone.ObjectsTotal, clone.Bytes = progress.Objects, progress.ObjectsTotal, progress.Bytes
	}
	return clone
}

